/**
 * PDF 缩放的**锚点换算**（纯函数，便于单测）。
 *
 * 要解决的问题：放大时视口里"刚才盯着的那一点"必须留在原处。
 * 直觉做法是 `scrollTop = (scrollTop + 焦点) * 倍数 - 焦点`，但它只在"整份文档等比放大"时才对：
 * 页面之间的 `gap` 与阅读区 `padding` **不随缩放变化**，所以在第 10 页附近会偏出上百像素
 * （实测：20 页的文档、放大 2 倍时，按倍率换算比真实位置少算 ~200px）。
 *
 * 所以锚点记的是"**哪一页 + 页内比例**"，缩放后再用同一页的新几何把它摆回去：
 * 页面高度等比变化、gap/padding 不变，这两件事都被自然吸收。
 *
 * 另一个要点：锚点必须**在整段手势里只捕获一次**。捏合会产生很多次缩放，
 * 如果每次都从"当前"滚动位置重新捕获，误差会一步步叠加（实测捏合 4 步就跑偏 0.117 页）。
 */
export interface PageBox {
  page: number;
  /** 页面上边缘在**内容坐标**里的位置（`rect.top - rootRect.top + scrollTop`）。 */
  top: number;
  /** 页面左边缘在内容坐标里的位置。 */
  left: number;
  width: number;
  height: number;
}

export interface ScrollSnapshot {
  scrollTop: number;
  scrollLeft: number;
  width: number;
  height: number;
}

export interface ZoomAnchor {
  page: number;
  /** 焦点在页面内的相对位置（0~1），横向同理。 */
  xFraction: number;
  yFraction: number;
  /** 焦点相对阅读区左上角的像素位置：缩放后要把锚点摆回这里。 */
  focusX: number;
  focusY: number;
}

const clamp = (value: number, min: number, max: number) => Math.min(Math.max(value, min), max);

/**
 * 捕获焦点下面的那一页。焦点落在页与页之间的空隙里时取最近的一页，
 * 比例收到 0~1（相当于吸附到最近的页边，不会把不存在的坐标记下来）。
 */
export function captureZoomAnchor(pages: PageBox[], scroll: ScrollSnapshot, focus: { x: number; y: number }): ZoomAnchor | null {
  const visible = pages.filter(page => page.height > 0 && page.width > 0);
  if (!visible.length) return null;
  const focusX = clamp(focus.x, 0, scroll.width);
  const focusY = clamp(focus.y, 0, scroll.height);
  const contentY = scroll.scrollTop + focusY;
  const contentX = scroll.scrollLeft + focusX;
  let best = visible[0]!;
  let bestDistance = Number.POSITIVE_INFINITY;
  for (const page of visible) {
    const insideY = contentY >= page.top && contentY <= page.top + page.height;
    const outside = Math.min(Math.abs(page.top - contentY), Math.abs(page.top + page.height - contentY));
    const distance = insideY ? 0 : outside;
    if (distance < bestDistance) {
      bestDistance = distance;
      best = page;
    }
  }
  return {
    page: best.page,
    xFraction: clamp((contentX - best.left) / best.width, 0, 1),
    yFraction: clamp((contentY - best.top) / best.height, 0, 1),
    focusX,
    focusY,
  };
}

/**
 * 缩放后要让锚点回到 `focus` 处所需的滚动位置。
 * 页面已经不在了（画布被回收/文档换了）就返回 null，调用方据此退回"按倍率换算"。
 * 结果按滚动范围夹紧——夹紧是必须的，否则滚到边界附近会设出一个被浏览器忽略的值。
 */
export function resolveZoomAnchor(
  anchor: ZoomAnchor,
  pages: PageBox[],
  scroll: { width: number; height: number; scrollWidth: number; scrollHeight: number },
): { top: number; left: number } | null {
  const page = pages.find(candidate => candidate.page === anchor.page && candidate.height > 0 && candidate.width > 0);
  if (!page) return null;
  const top = page.top + anchor.yFraction * page.height - anchor.focusY;
  const left = page.left + anchor.xFraction * page.width - anchor.focusX;
  return {
    top: clamp(top, 0, Math.max(0, scroll.scrollHeight - scroll.height)),
    left: clamp(left, 0, Math.max(0, scroll.scrollWidth - scroll.width)),
  };
}

/** 退路：页面找不到了，就按倍率换算（比不动好）。 */
export function ratioScroll(snapshot: ScrollSnapshot, focus: { x: number; y: number }, ratio: number, scroll: { scrollWidth: number; scrollHeight: number }) {
  const focusX = clamp(focus.x, 0, snapshot.width);
  const focusY = clamp(focus.y, 0, snapshot.height);
  return {
    top: clamp((snapshot.scrollTop + focusY) * ratio - focusY, 0, Math.max(0, scroll.scrollHeight - snapshot.height)),
    left: clamp((snapshot.scrollLeft + focusX) * ratio - focusX, 0, Math.max(0, scroll.scrollWidth - snapshot.width)),
  };
}
